/**
 * React hooks for next-i18n-auto
 * Optional React integration for easier usage in Next.js components
 */

import { useState, useEffect, useCallback } from 'react';
import { getLanguageSwitcher, LanguageSwitcherOptions } from './language-switcher';

/**
 * Hook to use language switching in React components
 */
export function useLanguage(options?: LanguageSwitcherOptions) {
  const [language, setLanguage] = useState<string>('en');
  const [isLoading, setIsLoading] = useState<boolean>(false);

  useEffect(() => {
    const switcher = getLanguageSwitcher(options);
    setLanguage(switcher.getCurrentLanguage());

    // Initialize on mount
    switcher.initialize().catch(console.error);

    // Listen for language changes
    const handleLanguageChange = (event: Event) => {
      const customEvent = event as CustomEvent<{ language: string }>;
      setLanguage(customEvent.detail.language);
    };

    window.addEventListener('languageChanged', handleLanguageChange);

    return () => {
      window.removeEventListener('languageChanged', handleLanguageChange);
    };
  }, []);

  const switchLanguage = useCallback(async (newLanguage: string) => {
    setIsLoading(true);
    try {
      const switcher = getLanguageSwitcher(options);
      await switcher.switchLanguage(newLanguage);
    } catch (error) {
      console.error('Error switching language:', error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  return {
    language,
    switchLanguage,
    isLoading
  };
}

/**
 * Hook to preload languages
 */
export function usePreloadLanguages(languages: string[], options?: LanguageSwitcherOptions) {
  useEffect(() => {
    const switcher = getLanguageSwitcher(options);
    switcher.preloadLanguages(languages).catch(console.error);
  }, [languages.join(',')]);
}
